# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of aten::index_select_backward.

Reference semantics:
    out = zeros(self_sizes, float32); out.index_add_(dim, index, grad.float())
    return out.to(grad.dtype)

With D = len(self_sizes), d = dim normalised,
O = prod(self_sizes[:d]), K = self_sizes[d], R = prod(self_sizes[d+1:]),
L = index.numel(), and grad viewed as X[O, L, R]:

    out[o, k, r] = sum_l [index[l] == k] * X[o, l, r]

Two deterministic kernels are used (no atomics, no zero-initialisation pass -
every output element is written, including the untouched k rows):

* ``_isb_det_kernel``  (R > 1): programs own an (o, k-block, r-block) tile with
  a BK x BR fp32 accumulator and walk l serially.
* ``_isb_reduce_kernel`` (R == 1): the r axis collapses to one element, so a
  serial walk over l is latency bound.  Programs own an (o, k-block) tile, pull
  the index and grad slices in chunks of BL and reduce the chunk along the l
  axis, keeping a BK-wide fp32 accumulator.
"""

import torch
import triton
import triton.language as tl


@triton.jit
def _isb_det_kernel(
    out_ptr,
    grad_ptr,
    idx_ptr,
    K,
    L,
    R,
    SO,
    SI,
    SR,
    BK: tl.constexpr,
    BR: tl.constexpr,
    ACC_T: tl.constexpr,
    OUT_T: tl.constexpr,
):
    pid_r = tl.program_id(0)
    pid_k = tl.program_id(1)
    o = tl.program_id(2)

    r = pid_r * BR + tl.arange(0, BR)
    rmask = r < R
    k = pid_k * BK + tl.arange(0, BK)
    kmask = k < K

    acc = tl.zeros((BK, BR), dtype=ACC_T)
    gbase = grad_ptr + o * SO
    for idx_pos in range(0, L):
        idx = tl.load(idx_ptr + idx_pos).to(tl.int32)
        g = tl.load(gbase + idx_pos * SI + r * SR, mask=rmask, other=0.0).to(ACC_T)
        acc += tl.where(k[:, None] == idx, g[None, :], 0)

    tl.store(
        out_ptr + (o * K + k[:, None]) * R + r[None, :],
        acc.to(OUT_T),
        mask=kmask[:, None] & rmask[None, :],
    )


@triton.jit
def _isb_reduce_kernel(
    out_ptr,
    grad_ptr,
    idx_ptr,
    K,
    L,
    SO,
    SI,
    BK: tl.constexpr,
    BL: tl.constexpr,
    ACC_T: tl.constexpr,
    OUT_T: tl.constexpr,
):
    pid_k = tl.program_id(0)
    o = tl.program_id(1)

    k = pid_k * BK + tl.arange(0, BK)
    kmask = k < K

    acc = tl.zeros((BK,), dtype=ACC_T)
    gbase = grad_ptr + o * SO
    for l0 in range(0, L, BL):
        ll = l0 + tl.arange(0, BL)
        lmask = ll < L
        idx = tl.load(idx_ptr + ll, mask=lmask, other=-1).to(tl.int32)
        g = tl.load(gbase + ll * SI, mask=lmask, other=0.0).to(ACC_T)
        acc += tl.sum(tl.where(k[:, None] == idx[None, :], g[None, :], 0), axis=1)

    tl.store(out_ptr + o * K + k, acc.to(OUT_T), mask=kmask)


_ACC_DTYPE = {
    torch.float16: tl.float32,
    torch.bfloat16: tl.float32,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
    torch.int8: tl.int32,
    torch.int16: tl.int32,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
}

_OUT_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
    torch.int8: tl.int8,
    torch.int16: tl.int16,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
}


def index_select_backward(grad, self_sizes, dim, index):
    sizes = [int(s) for s in self_sizes]
    nd = len(sizes)
    d = int(dim)
    if d < 0:
        d += nd

    L = int(index.numel())
    K = sizes[d]
    outer_size = 1
    for s in sizes[:d]:
        outer_size *= s
    R = 1
    for s in sizes[d + 1 :]:
        R *= s

    out = torch.empty(sizes, dtype=grad.dtype, device=grad.device)

    if index.dim() != 1 or index.stride(0) != 1:
        index = index.reshape(-1).contiguous()

    so, si, sr = _plane_strides(grad, d, L, R)
    acc_t = _ACC_DTYPE[grad.dtype]
    out_t = _OUT_DTYPE[grad.dtype]

    if R == 1:
        # dim is the innermost axis: reduce the index/grad slices along l.
        BL = min(256, triton.next_power_of_2(L)) if L > 0 else 1
        BK = max(1, min(256, triton.next_power_of_2(K), 8192 // BL))
        grid = (max(1, (K + BK - 1) // BK), max(1, outer_size))
        _isb_reduce_kernel[grid](
            out,
            grad,
            index,
            K,
            L,
            so,
            si,
            BK=BK,
            BL=BL,
            ACC_T=acc_t,
            OUT_T=out_t,
        )
        return out

    BK = min(256, triton.next_power_of_2(K)) if K > 0 else 1
    BR = min(32, triton.next_power_of_2(R)) if R > 0 else 1
    grid = (
        max(1, (R + BR - 1) // BR),
        max(1, (K + BK - 1) // BK),
        max(1, outer_size),
    )
    _isb_det_kernel[grid](
        out,
        grad,
        index,
        K,
        L,
        R,
        so,
        si,
        sr,
        BK=BK,
        BR=BR,
        ACC_T=acc_t,
        OUT_T=out_t,
    )
    return out


def _plane_strides(grad, d, L, R):
    """Return (SO, SI, SR) so that grad[o, l, r] is at o*SO + l*SI + r*SR."""
    nd = grad.dim()
    if grad.is_contiguous():
        return ((L * R) if d > 0 else 0), R, 1
    st = grad.stride()
    shp = grad.shape
    foldable = True
    for i in range(d - 1):
        if st[i] != st[i + 1] * shp[i + 1]:
            foldable = False
            break
    if foldable:
        for i in range(d + 1, nd - 1):
            if st[i] != st[i + 1] * shp[i + 1]:
                foldable = False
                break
    if not foldable:
        grad = grad.contiguous()
        return ((L * R) if d > 0 else 0), R, 1
    return (
        int(st[0]) if d > 0 else 0,
        int(st[d]),
        int(st[nd - 1]) if nd - 1 > d else 1,
    )
